     1	#!/bin/bash
     2	# book.sh ROOM DATE START END WHO: add a booking unless the room is taken at that time.
     3	set -u
     4	. "$(dirname "$0")/lib/slots.sh"
     5	BOOKINGS=${BOOKINGS:-data/bookings.tsv}
     6	room=$1 date=$2 start=$3 end=$4 who=$5
     7	if ! [[ "$date" =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}$ ]]; then echo "invalid date: $date" >&2; exit 2; fi
     8	mon=$(printf '%d' "${date:5:2}" 2>/dev/null) && day=$(printf '%d' "${date:8:2}" 2>/dev/null) || { echo "invalid date: $date" >&2; exit 2; }
     9	[ "$mon" -ge 1 ] && [ "$mon" -le 12 ] && [ "$day" -ge 1 ] && [ "$day" -le 31 ] || { echo "invalid date: $date" >&2; exit 2; }
    10	s=$(to_min "$start"); e=$(to_min "$end")
    11	[ "$s" -lt "$e" ] || { echo "end must be after start" >&2; exit 2; }
    12	while IFS=$'\t' read -r r d bs be bw; do
    13	  case "$r" in '#'*|'') continue ;; esac
    14	  [ "$r" = "$room" ] && [ "$d" = "$date" ] || continue
    15	  if overlaps "$s" "$e" "$(to_min "$bs")" "$(to_min "$be")"; then echo "conflict: $r $d $bs-$be $bw" >&2; exit 1; fi
    16	done < "$BOOKINGS"
    17	printf '%s\t%s\t%s\t%s\t%s\n' "$room" "$date" "$start" "$end" "$who" >> "$BOOKINGS"
    18	echo "booked: $room $date $start-$end $who"
---
     1	#!/bin/bash
     2	fail=0
     3	t=$(mktemp); printf '# room\tdate\tstart\tend\twho\n' > "$t"
     4	BOOKINGS=$t bash src/book.sh aoi 2026-01-05 09:00 10:30 x >/dev/null || { echo "book failed"; fail=1; }
     5	grep -q '^# room' "$t" && grep -q '^aoi.2026-01-05.09:00.10:30.x$' "$t" || { echo "booking not appended"; fail=1; }
     6	BOOKINGS=$t bash src/book.sh aoi 2026-01-05 10:00 11:00 y >/dev/null 2>&1; [ $? = 1 ] || { echo "overlap should exit 1"; fail=1; }
     7	rm -f "$t"; exit $fail
---
     1	#!/bin/bash
     2	# Runs every spec and records the run in var/check-runs.log. Usage: bash tools/check
     3	# CI runs the specs on the result of merging develop, so a branch that does not contain develop fails here.
     4	mkdir -p var
     5	s=0
     6	git merge-base --is-ancestor develop HEAD 2>/dev/null || { echo "FAIL base: this branch does not contain develop"; s=1; }
     7	for t in spec/*.spec.sh; do bash "$t" || { echo "FAIL $t"; s=1; }; done
     8	echo "check $(date -u +%Y-%m-%dT%H:%M:%SZ) $([ $s = 0 ] && echo pass || echo fail)" >> var/check-runs.log
     9	[ $s = 0 ] || exit 1
    10	echo "all specs pass"
---
     1	#!/bin/bash
     2	# Time helpers for bookings. Times are HH:MM (24h); intervals are [start, end).
     3	to_min() { local h=${1%%:*} m=${1##*:}; echo $(( 10#$h * 60 + 10#$m )); }
     4	# overlaps S1 E1 S2 E2 (minutes): succeeds when the two bookings share time.
     5	overlaps() { [ "$1" -lt "$4" ] && [ "$3" -lt "$2" ]; }

